s=open("region.fasta").read()
s="".join(l.strip() for l in s.splitlines() if not l.startswith(">")).upper()
comp=str.maketrans("ACGT","TGCA")
def rc(x): return x.translate(comp)[::-1]

codon_table={}
bases="TCAG"; aas="FFLLSSSSYY**CC*WLLLLPPPPHHQQRRRRIIIMTTTTNNKKSSRRVVVVAAAADDEEGGGG"; i=0
for b1 in bases:
    for b2 in bases:
        for b3 in bases:
            codon_table[b1+b2+b3]=aas[i]; i+=1
def translate(nt):
    return "".join(codon_table[nt[i:i+3]] for i in range(0,len(nt)-2,3))

def get(start,end,strand):  # 1-based inclusive on original seq
    if strand=='+': return s[start-1:end]
    else: return rc(s[start-1:end])

cands=[ (1,39,788), (1,1069,1444), (1,1783,2254),
        (-1,405,1398),
        (-1,1253,2210) ]

prot_seq_dict={}
for strand,a,b in cands:
    nt=get(a,b,strand)
    p=translate(nt)
    # trim trailing stop
    if p.endswith('*'): p=p[:-1]
    print(strand,a,b,"len(na)=%d len(aa)=%d"%(len(nt),len(p)),"internal stops:",p.count('*'),
          "startaa:",p[0:12],"endaa:",p[-6:])
    prot_seq_dict[(strand,a,b)]=p

# codon usage bias: count synonymous codon families
synfams={
 'L':['TTA','TTG','CTT','CTC','CTA','CTG'],'F':['TTT','TTC'],'S':['TCT','TCC','TCA','TCG','AGT','AGC'],
 'Y':['TAT','TAC'],'*':['TAA','TAG','TGA'],'C':['TGT','TGC'],'W':['TGG'],'P':['CCT','CCC','CCA','CCG'],
 'H':['CAT','CAC'],'Q':['CAA','CAG'],'R':['CGT','CGC','CGA','CGG','AGA','AGG'],'I':['ATT','ATC','ATA'],
 'M':['ATG'],'T':['ACT','ACC','ACA','ACG'],'N':['AAT','AAC'],'K':['AAA','AAG'],'V':['GTT','GTC','GTA','GTG'],
 'A':['GCT','GCC','GCA','GCG'],'D':['GAT','GAC'],'E':['GAA','GAG'],'G':['GGT','GGC','GGA','GGG']}

def biasreport(p):
    counts={}
    for aa in p:
        counts.setdefault(aa,0)
        counts[aa]+=1
    gct={}
    for aa,c in counts.items():
        if len(synfams[aa])>1 and c>=5:
            fam=synfams[aa]
            pct0=100*sum(1 for ch in fam if ch[2]=='T')/len(fam)
            pct3=100*sum(1 for ch in fam if ch[2]=='C')/len(fam)
            pct2=100*sum(1 for ch in fam if ch[2]=='A')/len(fam)
            pct1=100*sum(1 for ch in fam if ch[2]=='G')/len(fam)
            gct[aa]=(round(pct1,1),round(pct0,1),round(pct2,1),round(pct3,1))  # (G,T,A,C endings %)
    return gct

for k,p in prot_seq_dict.items():
    print(k, "GC-ending codon share by family (key: aa -> %(G,T,A,C endings)):", biasreport(p))
