# dot-plot style: find all pairs of positions sharing an exact 15-mer
from collections import defaultdict
k=15
d=defaultdict(list)
for i in range(n-k+1):
    d[s[i:i+k]].append(i)
pairs=[]
for kmer,pos in d.items():
    if len(pos)>1:
        for a in range(len(pos)):
            for b in range(a+1,len(pos)):
                pairs.append((pos[a],pos[b]))
print("repeated 15-mers (kmer, count, positions):")
for kmer,pos in d.items():
    if len(pos)>1:
        print(" ",kmer,pos)

# shift ladder: autocorrelation of match indicator (any of 4 letters matching at shift k)
best=[]
import math
for k in range(1,1201):
    M=sum(1 for i in range(n-k) if s[i]==s[i+k])
    mu=(n-k)*0.25; sd=math.sqrt((n-k)*0.75/4)
    z=(M-mu)/sd
    best.append((z,k,M))
best.sort(reverse=True)
print("\ntop overall shifts by z:")
for z,k,M in best[:15]: print(" shift %4d matches %4d z=%+.2f"%(k,M,z))
print("\ntop multiples of 3 only:")
for z,k,M in [x for x in best if x[1]%3==0][:10]: print(" shift %4d matches %4d z=%+.2f"%(k,M,z))
